<script setup lang="ts">
const state=useAtelier(),audio=useAudio(),{t,language}=useLocale(),settings=ref(false),musicOpen=ref(false)
function openSettings(){state.graphicsPrompt.value=false;musicOpen.value=false;settings.value=true}
function openMusic(){state.graphicsPrompt.value=false;settings.value=false;musicOpen.value=true}
function toggleGraphics(){settings.value=false;musicOpen.value=false;state.graphicsPrompt.value=!state.graphicsPrompt.value}
// One compact line under the header, once per browser: it dismisses itself after a few seconds, and a visitor who has
// already chosen graphics settings never sees it. The graphics panel itself only opens from its button.
let hintTimer:ReturnType<typeof setTimeout>|undefined
const hintKey='velocity-performance-tip-seen'
try{if(localStorage.getItem(hintKey)==='1'||localStorage.getItem('velocity-graphics-v1'))state.performanceHintDismissed.value=true}catch{}
watch(()=>state.performanceHintDismissed.value,seen=>{if(seen)try{localStorage.setItem(hintKey,'1')}catch{}})
watch(()=>state.graphicsPrompt.value,open=>{if(open)state.performanceHintDismissed.value=true})
watch(()=>state.sceneReady.value,ready=>{clearTimeout(hintTimer);if(ready)hintTimer=setTimeout(()=>{state.performanceHintDismissed.value=true},8000)},{immediate:true})
onBeforeUnmount(()=>clearTimeout(hintTimer))
// Photo mode (PhotoStudio) ends when the page is left.
onBeforeUnmount(()=>{state.photoMode.value=false})
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}}
</script>
<template>
 <header class="header"><NuxtLink to="/" class="wordmark">VELOCITY 3<span>AUTOMOBILI</span></NuxtLink><nav><NuxtLink to="/">{{t('Обзор','Experience')}}</NuxtLink><NuxtLink to="/garage">{{t('Гараж','Garage')}} <sup>08</sup></NuxtLink><NuxtLink :to="'/drive/'+state.car.value.id">{{t('В движении','In motion')}}</NuxtLink><NuxtLink to="/legal">{{t('Лицензии','Licenses')}}</NuxtLink></nav><div class="header-tools">
 <button class="tool-button language-button" :title="language==='ru'?'Switch to English':'Перевести на русский'" :aria-label="language==='ru'?'Switch to English':'Перевести на русский'" @click="language=language==='ru'?'en':'ru'">{{language==='ru'?'EN':'RU'}}</button>
 <button v-if="state.sceneReady.value" class="tool-button" :title="t('Фоторежим','Photo mode')" :aria-label="t('Фоторежим','Photo mode')" @click="state.photoMode.value=true"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 8.5h3.5l2-3h6l2 3h3.5v11h-17z"/><circle cx="12" cy="13.5" r="3.6"/></svg></button>
 <button class="tool-button" :title="t('Музыка','Music')" :aria-label="t('Музыка','Music')" :aria-expanded="musicOpen" @click="openMusic"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="2.2"/><path d="M7 9a6 6 0 0 1 4-3M13 18a6 6 0 0 0 4-3"/></svg></button>
 <button class="tool-button" :title="t('Настройки графики','Graphics settings')" :aria-label="t('Настройки графики','Graphics settings')" :aria-expanded="state.graphicsPrompt.value" @click="toggleGraphics"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3.5" width="18" height="13" rx="2"/><path d="M8 21h8M12 16.5V21M6.5 12l3-3 3 2 5-5"/></svg></button>
 <button class="tool-button" :title="t('Настройки','Settings')" :aria-label="t('Настройки','Settings')" :aria-expanded="settings" @click="openSettings"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9.5 3-.5 2-2 1-2-.5-2.5 4 1.5 1.5v2L2.5 14.5l2.5 4 2-.5 2 1 .5 2h5l.5-2 2-1 2 .5 2.5-4L20 13v-2l1.5-1.5-2.5-4-2 .5-2-1-.5-2z"/><circle cx="12" cy="12" r="3"/></svg></button>
 <button class="tool-button" :title="t('Полный экран','Fullscreen')" :aria-label="t('Полный экран','Fullscreen')"  @click="fullscreen"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg></button>
 </div></header>
 <PhotoStudio v-if="state.photoMode.value" />
 <aside v-if="state.graphicsPrompt.value" class="quick-graphics"><button class="dismiss-graphics" :aria-label="t('Закрыть настройки графики','Close graphics settings')" @click="state.graphicsPrompt.value=false">×</button><small>{{t('НАСТРОЙКИ ГРАФИКИ','GRAPHICS SETTINGS')}}</small><GraphicsControls /><button class="apply-graphics" @click="state.graphicsPrompt.value=false">{{t('Готово','Done')}}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg></button></aside>
 <AtelierDialog v-if="musicOpen" class="preferences-dialog" @close="musicOpen=false"><small>VELOCITY 3 / {{t('АУДИО','AUDIO')}}</small><h2>{{t('Музыка','Music')}}</h2><MusicPanel /></AtelierDialog>
 <AtelierDialog v-if="settings" class="preferences-dialog" @close="settings=false"><small>VELOCITY 3 / {{t('ПАРАМЕТРЫ','PREFERENCES')}}</small><h2>{{t('Настройки','Settings')}}</h2><div class="preference-list">
 <label>{{t('Тени','Shadows')}}<input class="switch" type="checkbox" v-model="state.shadows.value"></label>
 <label>{{t('Блики','Bloom')}}<input class="switch" type="checkbox" v-model="state.bloom.value"></label>
 <label>{{t('Вращение света','Rotate lighting')}}<input class="switch" type="checkbox" v-model="state.rotateLighting.value"></label>
 <label>{{t('Анимация камеры','Camera animation')}}<input class="switch" type="checkbox" v-model="state.motion.value"></label>
 <label>{{t('Звуки интерфейса','Interface sounds')}}<input class="switch" type="checkbox" v-model="state.sound.value" @change="audio.click()"></label>
 <label class="volume-control"><span>{{t('Громкость','Volume')}}<small>{{Math.round(state.volume.value*100)}}%</small></span><input type="range" min="0" max="1" step="0.01" v-model.number="state.volume.value" @change="audio.click()"></label>
 </div></AtelierDialog>

<Transition name="tip"><aside v-if="state.sceneReady.value&&!state.performanceHintDismissed.value&&!state.photoMode.value" class="performance-tip" role="status"><span>{{t('Если подтормаживает — снизьте качество','If it stutters, lower the quality')}}</span><button class="tip-settings" @click="settings=false;musicOpen=false;state.graphicsPrompt.value=true">{{t('Графика','Graphics')}} →</button><button class="tip-close" :aria-label="t('Закрыть подсказку','Dismiss tip')" @click="state.performanceHintDismissed.value=true">×</button></aside></Transition></template>



